  const askJob = id => { const j = s.jobs.find(x => x.id === id); if (!j) return; const gate = canReply(j); if (!gate.ok) return replyJob(id); open({ title: 'Ask ' + j.by.split(' ')[0] + ' first', sub: 'Goes to them before you quote. You can still quote after.', cta: 'Send', fields: [{ k: 'msg', l: 'Question', type: 'textarea', rows: 4, required: true, value: (s.brand.voice?.greet || 'Hi') + ' ' + j.by.split(' ')[0] + ', before I quote, can you tell me a bit more about ' + ({ Wedding: 'the timings and how many guests', 'Real estate': 'the properties and whether you need floorplans', Headshots: 'the room you have and how many people', Event: 'the run sheet and what you need on the day', Brand: 'where the photos will be used', Family: 'who is coming and where you would like to shoot' }[j.k] || 'the job') + '?' }], submit: v => { const r = jobThread(j, v.msg.trim()); upd('jobs', id, x => ({ my: { st: 'asked', at: TODAY, tid: r.tid, msg: v.msg.trim() } })); toast('Sent. A thread opened.'); nav('/app/thread/' + r.tid) } }) }
