  // The client's side: a reply arrives, they accept one, the others close, a thread opens
  const clientAccept = (jid, aid) => { const j = s.jobs.find(x => x.id === jid); if (!j) return; const a = (j.apps || []).find(x => x.id === aid); upd('jobs', jid, x => ({ st: 'filled', apps: x.apps.map(y => ({ ...y, st: y.id === aid ? 'accepted' : y.st === 'declined' ? 'declined' : 'closed' })), ...(x.my ? { my: { ...x.my, st: a?.mine ? 'won' : 'lost' } } : {}) })); if (a?.mine && j.my?.tid) { upd('threads', j.my.tid, { stage: 2, next: 'Quote accepted from the job board. Send the contract.' }); const q = s.ledger.find(x => x.id === j.my.q); if (q) upd('ledger', q.id, { st: 'ok', stt: 'Accepted' }) } return a }
