  const postClientJob = v => { const loc = v.loc.trim(); const id = add('jobs', { t: v.t.trim(), k: v.k, ct: v.ct, loc, state: (loc.match(/\b(QLD|NSW|VIC|SA|WA|TAS|NT|ACT)\b/i) || ['', 'QLD'])[1].toUpperCase(), km: kmOf(loc), d: v.d || '', flex: v.d ? '' : (v.flex || 'Flexible'), b: Number(v.b) || 0, hrs: v.hrs || '', w: v.w.trim(), by: v.by.trim(), kind: 'client', posted: TODAY, expires: addDays(TODAY, 30), replies: 0, g: GR[s.jobs.length % GR.length], st: 'open', verified: 0, prior: s.jobs.filter(x => x.client?.em && x.client.em === v.em).length, apps: [], client: { n: v.by.trim(), em: v.em.trim(), ph: (v.ph || '').trim() } }, 'job'); return id }
  // ── reviews ─────────────────────────────────────────────────────────────
