  const draftReply = r => { const v = s.brand.voice || {}; const tone = v.tone || []; const f = first(r.who); const lines = r.n >= 5 ? [`Thank you ${f}, that means a lot.`, r.job === 'Wedding' || r.job === 'Elopement' ? 'Your day was a joy to be part of.' : `Loved working on the ${r.job.toLowerCase()} with you.`, 'See you next time.'] : r.n === 4 ? [`Thanks ${f}, really appreciate you taking the time.`, 'Noted on the bit that could have been better; that is on me for next time.'] : [`Thank you for the honest note, ${f}.`, 'I would love to make this right. I will message you directly today.']; const out = (tone.includes('Direct') || tone.includes('Understated') ? lines.slice(0, 2) : lines).join(' '); return out + (v.signoff ? '\n' + v.signoff : '') }
